mkdir -p /tmp/actcheck && cat > /tmp/actcheck/cdp.mjs <<'EOF'
// Throwaway helper: launch headless Chrome, expose send/eval/click/key/shot.
import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';
const CHROME = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
export async function open(url, { width = 1100, height = 1400, zoom = 1 } = {}) {
  const proc = spawn(CHROME, ['--headless=new', '--remote-debugging-port=9333',
    '--user-data-dir=/tmp/actcheck/profile', '--no-first-run', `--window-size=${width},${height}`, 'about:blank'],
    { stdio: 'ignore' });
  let targets;
  for (let i = 0; i < 50; i++) {
    try { targets = await (await fetch('http://127.0.0.1:9333/json')).json(); break; }
    catch { await new Promise(r => setTimeout(r, 200)); }
  }
  const page = targets.find(t => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise(r => ws.addEventListener('open', r, { once: true }));
  let id = 0; const pending = new Map();
  ws.addEventListener('message', m => { const d = JSON.parse(m.data); if (pending.has(d.id)) { pending.get(d.id)(d); pending.delete(d.id); } });
  const send = (method, params = {}) => new Promise(r => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
  await send('Page.enable'); await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: zoom, mobile: false });
  await send('Page.navigate', { url }); await new Promise(r => setTimeout(r, 800));
  const evaluate = async (expr) => (await send('Runtime.evaluate', { expression: expr, returnByValue: true })).result.result.value;
  const click = async (selector) => {
    const box = await evaluate(`(() => { const r = document.querySelector(${JSON.stringify(selector)}).getBoundingClientRect(); return { x: r.x + r.width / 2, y: r.y + r.height / 2 }; })()`);
    for (const type of ['mousePressed', 'mouseReleased'])
      await send('Input.dispatchMouseEvent', { type, x: box.x, y: box.y, button: 'left', clickCount: 1 });
    await new Promise(r => setTimeout(r, 50));
  };
  const key = async (k, code, keyCode, text) => {
    await send('Input.dispatchKeyEvent', { type: 'keyDown', key: k, code, windowsVirtualKeyCode: keyCode, text });
    await send('Input.dispatchKeyEvent', { type: 'keyUp', key: k, code, windowsVirtualKeyCode: keyCode });
    await new Promise(r => setTimeout(r, 50));
  };
  const shot = async (path) => writeFileSync(path, Buffer.from((await send('Page.captureScreenshot', { format: 'png' })).result.data, 'base64'));
  const close = () => { ws.close(); proc.kill(); };
  return { send, evaluate, click, key, shot, close };
}
EOF
cat > /tmp/actcheck/types.mjs <<'EOF'
import { open } from './cdp.mjs';
const p = await open('file://' + process.argv[2] + '/public/activity.html');
const state = () => p.evaluate(`({ visible: [...document.querySelectorAll('#activity-table tbody tr')].filter(r => !r.hidden).map(r => r.cells[1]?.textContent ?? r.textContent), status: document.getElementById('filter-status').textContent, errors: window.__errors })`);
const summary = async (label) => { const s = await state(); const counts = {}; for (const t of s.visible) counts[t] = (counts[t] || 0) + 1; console.log(label, '|', s.status, '|', JSON.stringify(counts)); };
await summary('initial');
await p.shot('/tmp/actcheck/types-initial.png');
await p.click('#types-none'); await summary('after Clear all');
await p.click('input[value="Sign-in failed"]'); await summary('after checking Sign-in failed');
for (const t of ['Password changed', 'Two-factor enabled', 'Email change requested', 'Settings updated']) await p.click(`input[value="${t}"]`);
await summary('plus 4 security types');
await p.shot('/tmp/actcheck/types-security.png');
await p.click('#types-all'); await summary('after Select all');
// keyboard: focus first checkbox via Tab from body, Space toggles it
await p.evaluate('document.activeElement.blur()');
await p.key('Tab', 'Tab', 9); 
console.log('focused after Tab:', await p.evaluate(`document.activeElement.outerHTML`));
console.log('focus outline:', await p.evaluate(`getComputedStyle(document.activeElement).outlineStyle + ' ' + getComputedStyle(document.activeElement).outlineWidth + ' ' + getComputedStyle(document.activeElement).outlineColor + ' offset ' + getComputedStyle(document.activeElement).outlineOffset`));
await p.key(' ', 'Space', 32, ' '); await summary('after Space on first checkbox');
await p.shot('/tmp/actcheck/types-focus.png');
p.close();
EOF
cd /tmp/actcheck && node types.mjs "$OLDPWD"

